missions.mission_launch = assert(load("-- Engine-held launch uses render ticks; ordinary missions use logic frames.\nreturn function(D)\n  local L={}\n  function L.begin(r,q)\n    if r.launch then return end\n    r.last_install_error=nil;r.pending_error=nil\n    r.launch={frames=0,engine=q.pending==true}\n    local accepted,why=pcall(function()\n      local command\n      if type(q.mission)=='string'and q.mission~=''then D.validator.name(q.mission);command='play '..q.mission\n      elseif q.size and q.size>0 then command=('maze %d %d'):format(q.seed,q.size)\n      else error('launch needs a mission or maze')end\n      r.launch.command=command\n      local ok,reason=r:command(command);assert(ok,reason)\n    end)\n    if not accepted then L.cancel(r,why)end\n  end\n  function L.cancel(r,why)\n    local launch=r.launch;r.launch=nil\n    if launch and launch.engine and r.g.launch_cancel then r.g.launch_cancel(tostring(why))end\n    r.g.log('mission: launch refused '..tostring(why))\n  end\n  function L.tick(r)\n    local q=r.launch;if not q then return end\n    q.frames=q.frames+1\n    if r.last_install_error or r.recovery then L.cancel(r,r.last_install_error or 'staging recovery required');return end\n    if q.engine then\n      if r.staging then D.install.tick(r)\n      elseif r.pending then r:retry()end\n      if D.maze_commands then D.maze_commands.settle(r)end\n    end\n    if r.pending_error or r.last_install_error or r.recovery then L.cancel(r,r.pending_error or r.last_install_error or 'staging recovery required');return end\n    if r.current and not r.staging and not r.pending then\n      if not q.engine or not r.g.launch_ready or r.g.launch_ready()then r.launch=nil;return end\n    end\n    if q.frames>=7200 then L.cancel(r,'mission launch timed out after 7200 ticks')end\n  end\n  function L.autostart(r)\n    if r.launch then return end\n    local q=r.g.launch_request and r.g.launch_request()\n    if q and q.pending then return end -- engine delivers the selected on_launch owner\n    local data=D.loader.data(r.g,'missions/autostart.lua',true)\n    if data then L.begin(r,data);return end\n    -- A level may opt in. Refuse ambiguity, never choose an arbitrary folder.\n    local selected;local entries=r.g.mod_list('missions/')or{}\n    if #entries>64 then r.g.log('mission: autostart scan exceeds 64 folders; use missions/autostart.lua');return end\n    for _,e in ipairs(entries)do if e.dir and type(e.name)=='string'and e.name:match('^[%w_-]+$')then\n      local level=D.loader.data(r.g,'missions/'..e.name..'/level.lua',true)\n      if level and level.autostart==true then\n        if selected then r.g.log('mission: ambiguous level autostart; use missions/autostart.lua');return end\n        selected=e.name\n      end\n    end end\n    if selected then L.begin(r,{mission=selected})end\n  end\n  return L\nend\n", "@missions/mission_launch.lua", "t"))()(missions)
missions.runtime = assert(load("-- Transaction coordinator and lifecycle; module factories also load under plain Lua.\nreturn function(D)\n  local R={};R.__index=R\n  function R.new(g)\n    local r=setmetatable({g=g,current=nil,generation=0,poll=0,guests={fighters={}}},R)\n    g.command('mission',function(arg) return r:command(arg) end,'Standalone mission folders and fly fixtures')\n    return r\n  end\n  function R:attempt(arg)\n    local op=arg:match('^%s*(%S+)')\n    if op=='play' or op=='reload' or op=='restart' or op=='fly' or op=='drop' or ((op=='maze'or op=='world')and not arg:match('%s+map%s*$')) then\n      if not D.fighters.ready(self.g.player(1)) or ((op=='play' or op=='reload' or op=='restart') and not D.fighters.stage_ready(self.g)) then return nil,'waiting for controllable P1',true end\n    end\n    local ok,why=pcall(D.commands.dispatch,self,arg)\n    return ok,why,not ok and D.fighters.transient(why)\n  end\n  function R:command(arg)\n    arg=arg or '';self.pending=nil;self.pending_error=nil\n    if (self.staging or self.recovery or self.stopping or self.world_generation)and not arg:match('^%s*stop%s*$')then\n      local why=self.stopping and 'mission cleanup pending; mission stop retries' or self.recovery and 'staging recovery required; mission stop retries cleanup' or 'mission installation already in progress'\n      self.g.log('mission: refused '..why);return nil,why\n    end\n    local op=arg:match('^%s*(%S+)')\n    local replacing=op=='play'or op=='reload'or op=='restart'or op=='stop'or((op=='maze'or op=='world')and not arg:match('%s+map%s*$'))\n    if self.current and self.current.run.finish and (op=='fly'or op=='drop'or op=='tour'or op=='clear')then\n      return nil,'mission ended; restart, reroll or stop'\n    end\n    local ok,why,retry=self:attempt(arg)\n    if retry then\n      if D.mission_finish and replacing then D.mission_finish.release(self,op~='stop')end\n      self.pending={arg=arg,frames=0};self.g.log('mission: '..arg..' waiting for controllable P1 (600-frame limit)');return true\n    end\n    if not ok then self.g.log('mission: refused '..tostring(why));return nil,why end\n    if D.mission_finish and replacing then D.mission_finish.release(self,op~='stop')end\n    return true\n  end\n  function R:retry()\n    local pending=self.pending;if not pending then return end\n    pending.frames=pending.frames+1\n    if pending.frames%6==0 then\n      local ok,why,retry=self:attempt(pending.arg)\n      if ok or not retry then\n        self.pending=nil\n        if not ok then self.pending_error=tostring(why);self.g.log('mission: refused '..tostring(why))end\n        return\n      end\n    end\n    if pending.frames>=600 then\n      self.pending=nil;self.pending_error=pending.arg..' timed out waiting for controllable P1';self.g.log('mission: '..self.pending_error)\n    end\n  end\n  function R:dispose(c)\n    if not c then return end\n    if c==self.current then D.commands.cancel(self)end\n    D.glue.cleanup(self.g,c.run)\n    D.chunks.stop(c.stream)\n    if c.root then D.world.unload(self.g,c.root) end\n    for _,asset in pairs(c.asset_pool or {}) do pcall(self.g.model_release,asset) end\n  end\n  function R:stop(reason)\n    local g=self.g;self.pending=nil\n    if D.mission_finish then D.mission_finish.release(self)end\n    if D.world_commands then D.world_commands.cancel(self)end\n    if self.stopping and self.stopping.blocked then self.stopping=nil end\n    if self.recovery then self.staging=self.recovery;self.recovery=nil;self.staging.step_key=nil end\n    if self.staging then\n      local match=g.match()\n      if not match or not match.active or match.netplay or reason=='unload' or reason=='state load unsupported' then D.install.abandon(self)\n      else self.staging.stop_reason=reason;D.install.fail(self,'staging cancelled: '..tostring(reason));return end\n    end\n    local match=g.match()\n    if self.current and match and match.active and not match.netplay then\n      -- Settlement precedes a queued scene launch: retire the old floor only after\n      -- leaving grounded callbacks, while its collision is still live.\n      local ok,why=pcall(function()g.fly_attack(1,false);g.fly(1,true);g.fly(1,false)end)\n      if not ok then\n        if not self.stopping then self.stopping={reason=reason,frames=0};g.log('mission: cleanup waiting for airborne P1: '..tostring(why))end\n        return\n      end\n    end\n    self.stopping=nil\n    D.install.dispose_retired(self)\n    D.camera.stop(g)\n    local guests=self.current or self.guests\n    if self.current then self:dispose(self.current);self.current=nil end\n    pcall(g.fly_attack,1,false);pcall(g.fly,1,false)\n    pcall(g.stage_hide,false);pcall(g.stage_restore_bounds)\n    D.fighters.stop(g,guests)\n    self.guests={fighters={}};self.guarded=nil;self.host_bounds=nil;self.host_spawns=nil\n    if reason=='match end'or reason=='unload'then self.autostart_checked=nil end\n    if self.launch and D.mission_launch then D.mission_launch.cancel(self,reason)end\n    g.log('mission: stopped '..tostring(reason))\n  end\n  function R:install(name,marker,reload) return D.install.begin(self,name,marker,reload) end\n  function R:match_start()\n    if self.staging then return end -- partial CPU reservations belong to this transaction\n    local match=self.g.match()\n    if match and match.active and not match.netplay then\n      self.guarded=D.fighters.guard(self.g,self.guests)\n      if D.mission_launch and not self.autostart_checked then self.autostart_checked=true;local ok,why=pcall(D.mission_launch.autostart,self)\n        if not ok then self.g.log('mission: autostart refused '..tostring(why))end end\n    end\n  end\n  function R:pre_frame()\n    local match=self.g.match()\n    if match and match.active and not match.netplay then\n      if not self.guarded then self:match_start() end\n      -- Retirement shares the active frame mutation budget below.\n    end\n  end\n  function R:frame()\n    local match=self.g.match()\n    if not match or not match.active or match.netplay then\n      if self.current or self.pending or self.staging or self.recovery or self.world_generation or next(self.guests.fighters) then self:stop('match end') end;return\n    end\n    if not self.guarded then self:match_start() end\n    if self.stopping then\n      local t=self.stopping;t.frames=t.frames+1\n      if t.frames==120 then t.blocked=true;self.g.log('mission: cleanup refused after 120 frames; mission stop retries');return end\n      if not t.blocked and t.frames%6==0 then self:stop(t.reason)end\n      return\n    end\n    if self.launch and self.launch.engine then return end\n    if self.staging then\n      D.install.tick(self)\n      if D.maze_commands then D.maze_commands.settle(self)end\n      if D.world_commands then D.world_commands.settle(self)end\n      if D.mission_finish then D.mission_finish.tick(self)end\n      return\n    end\n    if self.recovery then return end\n    D.camera.release(self.g) -- also release a rollback pose when no mission is active\n    self:retry()\n    if self.staging then return end\n    if D.world_commands then D.world_commands.tick(self)end\n    if self.staging then return end\n    if not self.current then return end\n    self.poll=self.poll+1\n    if self.poll%15==0 and not self.pending and not self.world_generation and D.fighters.ready(self.g.player(1)) then\n      local c=self.current\n      if not D.loader.same(c.doc.stamps,D.loader.stamps(self.g,c.doc.folder)) then self:command('reload');return end\n    end\n    local c=self.current\n    c.run.frames=c.run.frames+1\n    local ok,why=pcall(function()\n      local player=self.g.player(1) -- one post-physics observation for all bookkeeping\n      local membership=D.zones.sample(self.g,c,player,c.run.frames)\n      player=membership.point\n      D.glue.step(self.g,c,player)\n      local streamed,err=D.chunks.update(c.stream,player,membership)\n      if not streamed then self.g.log('mission: chunk refused '..tostring(err))end\n      if self.retiring and c.stream.load_frame~=membership.frame and c.stream.wave_frame~=membership.frame then\n        c.stream.load_frame=membership.frame;D.install.retire(self)\n      end\n      if D.maze_rewards then D.maze_rewards.tick(self.g,c) end\n      D.fighters.tick(self.g,c)\n      D.camera.tick(self.g,c,player)\n      D.commands.tick(self)\n      if D.mission_finish then D.mission_finish.tick(self)end\n    end)\n    if not ok then self.g.log('mission: frame refused '..tostring(why)) end\n  end\n  function R:tick()\n    if D.mission_launch then D.mission_launch.tick(self)end\n  end\n  function R:launch_start(q)\n    if D.mission_launch then D.mission_launch.begin(self,q)end\n  end\n  function R:draw()\n    if self.staging and D.mission_warm then D.mission_warm.draw(self.g,self.staging);return end\n    D.hud.draw(self.g,self.current)\n    if self.world_generation then self.g.text(16,88,'Generating world - please wait')end\n  end\n  return R\nend\n", "@missions/runtime.lua", "t"))()(missions)
missions.mission_launch = nil -- Envoy owns explicit scene/run launch; no standalone autostart.
local envoy = {loader=missions.loader, maze_set=missions.maze_set, maze=missions.maze}
envoy.pickup_juice = assert(load("-- Reusable offline pickup presentation. Embed this factory in sandbox entries (no require).\n-- One gd.items() snapshot per tick; effects never decide rewards or item physics.\nlocal J={}\nJ.defaults={glow=true,pool=true,sparkles=true,highlight=true,pop_trail=true,collect_burst=true,\n sound=true,hud_flash=true,blink=true,streak_frames=90,streak_step=70,streak_cap=900,\n max_effect_drops=30,max_collect_bursts=12,core_height=5.6875,drop_sound=246,pickup_sound=170,white_sound=250,volume=90,flash_frames=24}\nJ.pitch={red=-100,green=200,blue=0,yellow=100,white=300}\nlocal function call(f,...) if type(f)~='function' then return nil end;local ok,r=pcall(f,...);if ok then return r end end\nfunction J.new(g,settings)\n local s={};for k,v in pairs(J.defaults) do s[k]=v end;for k,v in pairs(settings or {}) do s[k]=v end\n local v={g=g,s=s,drops={},transients={},flash={},frame=0,streak=0,last=nil,seed=0}\n local function finish(h) if h then call(g.fx_end,h,0) end end\n local function play(kind,c,x,y,z)\n  v.seed=(v.seed+1)%2147483647\n  local h=call(g.fx_world,'PickupJuice_'..kind..'_'..c,x,y,z or 0,1,v.seed)\n  if not (type(h)=='number' and h>0) and not v.warned then\n   v.warned=true;call(g.log,'pickup juice: FX unavailable; mount the owning mod at boot (effects disabled safely)')\n  end\n  return type(h)=='number' and h>0 and h or nil\n end\n local function kill(d) for _,h in pairs(d.fx) do finish(h) end;d.fx={} end\n function v:drop(id,colour,x,y,lifetime)\n  if self.drops[id] then self:expire(id) end\n  colour=J.pitch[colour] and colour or 'white'\n  local d={colour=colour,x=x,y=y,z=0,age=0,lifetime=lifetime or 900,fx={}}\n  self.drops[id]=d\n  if s.sound then call(g.play_sound,s.drop_sound,{volume=s.volume,pitch=J.pitch[colour]}) end\n  local active=0;for _,other in pairs(self.drops) do if next(other.fx) then active=active+1 end end\n  if active<s.max_effect_drops then\n  for _,kind in ipairs({'glow','pool','sparkles','highlight','pop_trail'}) do\n   if s[kind] then d.fx[kind]=play(kind,colour,x,y+(kind=='pool' and .15 or 6+s.core_height),0) end\n  end\n  end\n  return d\n end\n function v:expire(id) local d=self.drops[id];if d then kill(d);self.drops[id]=nil end end\n function v:collect(id,colour,collector)\n  local d=self.drops[id];if not d then return nil end\n  colour=d.colour;self:expire(id)\n  if not self.last or self.frame-self.last>s.streak_frames then self.streak=0 else self.streak=self.streak+1 end\n  self.last=self.frame\n  local pitch=math.min(1200,J.pitch[colour]+math.min(s.streak_cap,self.streak*s.streak_step))\n  if s.sound then call(g.play_sound,colour=='white' and s.white_sound or s.pickup_sound,{volume=s.volume,pitch=pitch}) end\n  if s.hud_flash then self.flash[colour]=s.flash_frames end\n  if s.collect_burst then\n   if #self.transients>=s.max_collect_bursts then finish(self.transients[1].h);table.remove(self.transients,1) end\n   local h=play('collect_burst',colour,d.x,(d.visual_y or d.y+6)+s.core_height,d.z)\n   if h then self.transients[#self.transients+1]={h=h,left=24,total=24,x=d.x,y=(d.visual_y or d.y+6)+s.core_height,z=d.z,target=collector} end\n  end\n  return pitch\n end\n function v:tick()\n  self.frame=self.frame+1\n  local by={};for _,r in ipairs(call(g.items) or {}) do if r.handle then by[r.handle]=r end end\n  for id,d in pairs(self.drops) do\n   d.age=d.age+1;local r=by[id]\n   if r then d.seen=true;d.age=r.age or d.age;d.x=r.x;d.y=r.y;d.z=r.z or 0;d.visual_y=r.visual_y or r.y+6 end\n   if (type(id)=='number' and not r and (d.seen or d.age>2)) or d.age>=d.lifetime then self:expire(id)\n   else\n    local visible=not r or r.visible~=false or not s.blink\n    local opacity=visible and 1 or 0\n    for kind,h in pairs(d.fx) do\n     local x,y,z=d.x,(d.visual_y or d.y+6)+s.core_height,d.z\n     if kind=='pool' then y=d.y+.15\n     elseif kind=='highlight' then local angle=r and math.rad(r.rotation or 0) or d.age*math.pi/30;x=x+math.cos(angle)*3;y=y+math.sin(angle)*1.2;z=z+math.sin(angle)*3 end\n     call(g.fx_move,h,x,y,z)\n     -- fx_control overwrites all controls: specify brightness to preserve pop emphasis.\n     local bright=(kind=='pop_trail' or (kind=='glow' and s.pop_trail and d.age<24)) and 2 or 1\n     if d.opacity~=opacity or (kind=='glow' and d.age==24) or (kind=='pop_trail' and d.age==1) then\n      call(g.fx_control,h,-1,{opacity=opacity,brightness=bright},0)\n     end\n     if kind=='pop_trail' and d.age>=24 then finish(h);d.fx[kind]=nil end\n    end\n    d.opacity=opacity\n   end\n  end\n  for c,n in pairs(self.flash) do self.flash[c]=n>1 and n-1 or nil end\n  for i=#self.transients,1,-1 do\n   local t=self.transients[i];t.left=t.left-1\n   if t.left<=0 then finish(t.h);table.remove(self.transients,i)\n   elseif t.target then\n    local f=1-t.left/t.total\n    call(g.fx_move,t.h,t.x+(t.target.x-t.x)*f,t.y+(t.target.y-t.y)*f,t.z)\n   end\n  end\n end\n function v:clear()\n  for id in pairs(self.drops) do self:expire(id) end\n  for _,t in ipairs(self.transients) do finish(t.h) end\n  self.transients={};self.flash={};self.streak=0;self.last=nil\n end\n return v\nend\nreturn J\n", "@lib/pickup_juice.lua", "t"))()
envoy.mod_schema = assert(load("-- Only a shared vocabulary can express rules. No move IDs or modifier references.\nreturn function()\n local S={}\n local function set(words) local out={};for w in words:gmatch('%S+') do out[w]=true end;return out end\n S.tags=set('jab tilt smash aerial special grab throw projectile dash_attack grounded airborne normal fire electric ice darkness burning shocked chilled cursed hasted guarded momentum damage healing unique keystone')\n S.events=set('equip hit_dealt hit_taken ko_dealt stock_lost shield_hit perfect_shield clank jump air_jump landing ledge_grab grab throw taunt item_pickup stage_start interval status_applied status_removed stacks_changed')\n S.statuses=set('burn chill curse haste guarded momentum') -- Shock's hitstun effect awaits safe hit mutation.\n S.values=set('damage_dealt damage_taken run_speed air_speed shield_max jump_height air_jump_height knockback_taken fall_speed weight shield_regen')\n S.status_bits={burn=1,chill=4,curse=8,haste=16,guarded=32,momentum=64}\n S.hit_moves=set('any unknown jab dash_attack tilt smash aerial special grab throw projectile')\n S.elements=set('normal fire electric ice darkness')\n local record=set('id label kind cost tags tiers trigger interval conditions effects stacking text visual')\n local cond=set('tag self_status target_status status self_damage_above self_damage_below target_damage_above grounded airborne last_stock recently stage_kind')\n local fields={status=set('op status subject duration amount max refresh when'),value=set('op key value when'),heal=set('op amount subject when'),damage=set('op amount subject when'),stacks=set('op status subject duration amount max refresh when'),remove_status=set('op status subject when'),emit=set('op event subject tag when')}\n fields.convert=set('op match change');fields['versus-status']=set('op status match change')\n local function keys(t,allowed) assert(type(t)=='table' and not getmetatable(t),'plain record required');for k in pairs(t) do assert(allowed[k],'unsupported record field '..tostring(k)) end end\n local function number(v,m)\n  if type(v)=='string' then assert(v:match('^%$[a-z_]+$'),'only tier references allowed');for _,tier in ipairs(m.tiers) do assert(type(tier[v:sub(2)])=='number','missing tier value') end\n  else assert(type(v)=='number' and v==v and math.abs(v)<=100000,'finite bounded value required') end\n end\n local function array(t,minimum,maximum)\n  assert(type(t)=='table' and not getmetatable(t),'dense array required');local n=0\n  for k in pairs(t) do assert(type(k)=='number' and k%1==0 and k>=1,'dense array required');n=n+1 end\n  assert(n==#t and n>=minimum and n<=maximum,'array size out of bounds');for i=1,n do assert(t[i]~=nil,'dense array required') end\n end\n local function range(v,m,lo,hi,integer)\n  number(v,m);for i=1,#m.tiers do local x=type(v)=='string' and m.tiers[i][v:sub(2)] or v\n   assert(x>=lo and x<=hi and (not integer or x%1==0),'parameter out of bounds') end\n end\n function S.validate(m)\n  keys(m,record);assert(type(m.id)=='string' and m.id:match('^[a-z][a-z_]+$') and #m.id<=40,'invalid modifier id')\n  assert(type(m.label)=='string' and #m.label<=50 and type(m.text)=='string','label/text required')\n  assert(m.kind=='normal' or m.kind=='unique' or m.kind=='keystone','invalid rarity')\n  if m.kind~='normal' then assert(type(m.cost)=='string' and #m.cost>0,'rule-breaker needs explicit cost') end\n  array(m.tags,0,8);for _,tag in ipairs(m.tags) do assert(S.tags[tag],'tag must be vocabulary, never a move/modifier name') end\n  array(m.tiers,1,5)\n  for _,tier in ipairs(m.tiers) do assert(type(tier)=='table');for k,v in pairs(tier) do assert(type(k)=='string' and k:match('^[a-z_]+$'));number(v,m);assert(type(v)=='number','numeric tier required') end end\n  assert(S.events[m.trigger],'unsupported trigger')\n  if m.trigger=='interval' then range(m.interval,m,1,3600,true) else assert(m.interval==nil,'interval requires interval trigger') end\n  array(m.conditions or {},0,8)\n  if m.trigger=='equip' then assert(#(m.conditions or {})==0,'passive equip conditions unsupported') end\n  for _,c in ipairs(m.conditions or {}) do keys(c,cond);for k,v in pairs(c) do\n   if k=='tag' then assert(S.tags[v],'condition tag must be vocabulary')\n   elseif k=='self_status' or k=='target_status' or k=='status' then assert(v=='any' or S.statuses[v],'unsupported status condition')\n   elseif k=='recently' then keys(v,set('event frames'));assert(S.events[v.event]);range(v.frames,m,1,3600,true)\n   elseif k=='stage_kind' then assert(set('battle team giant metal bonus boss')[v],'unsupported stage kind')\n   elseif k=='grounded' or k=='airborne' or k=='last_stock' then assert(type(v)=='boolean') else number(v,m) end\n  end end\n  array(m.effects,1,8)\n  for _,e in ipairs(m.effects) do assert(fields[e.op],'unsupported effect (no connecting-hit mutation)');keys(e,fields[e.op])\n   if e.subject then assert(e.subject=='self' or e.subject=='target','unsupported effect subject') end\n   if e.when then assert(e.when==m.trigger,'effect event must match trigger') end\n   if e.op=='convert' or e.op=='versus-status' then\n    assert(m.trigger=='equip','native hit rules require unconditional equip')\n    keys(e.match,set('move grounded element incoming'));assert(e.match.move==nil or S.hit_moves[e.match.move],'hit match must use vocabulary')\n    assert(e.match.element==nil or S.elements[e.match.element],'only ordinary original elements supported')\n    if e.match.grounded~=nil then assert(type(e.match.grounded)=='boolean') end\n    if e.match.incoming~=nil then assert(type(e.match.incoming)=='boolean') end\n    if e.op=='convert' then\n     assert(not e.match.incoming,'incoming rules cannot modify creation')\n     keys(e.change,set('element damage knockback_growth knockback_base shield_damage hitstun'))\n     if e.change.element then assert(S.elements[e.change.element],'special element conversion refused') end\n    else\n     assert(e.match.incoming or S.status_bits[e.status],'versus-status requires a shared status or incoming match')\n     if e.status then assert(S.status_bits[e.status],'unknown status') end\n     keys(e.change,set('damage knockback_taken'))\n    end\n    assert(next(e.change),'native change required')\n    for k,v in pairs(e.change) do\n     if k=='shield_damage' then range(v,m,0,50,true) elseif k=='hitstun' then range(v,m,0,30,true)\n     elseif k~='element' then range(v,m,.1,4) end\n    end\n   elseif e.op=='value' then assert(m.trigger=='equip' and S.values[e.key],'fighter values require unconditional equip');range(e.value,m,.1,4)\n   elseif e.op=='status' or e.op=='stacks' then assert(m.trigger~='equip' and S.statuses[e.status],'unsupported status');range(e.duration,m,1,3600,true);range(e.amount or 1,m,0,100);assert(e.refresh=='refresh' or e.refresh=='extend' or e.refresh=='keep');assert(type(e.max)=='number' and e.max%1==0 and e.max>=1 and e.max<=8)\n   elseif e.op=='remove_status' then assert(S.statuses[e.status])\n   elseif e.op=='emit' then assert(S.events[e.event] and S.tags[e.tag]) else range(e.amount,m,0,100) end\n  end\n  keys(m.stacking,set('max'));assert(m.stacking.max==1,'step1 equips each rule once')\n  keys(m.visual,set('look hue strength priority'));assert(set('burn shock chill curse haste guarded momentum')[m.visual.look]);assert(type(m.visual.hue)=='number' and m.visual.hue>=0 and m.visual.hue<=1 and type(m.visual.strength)=='number' and m.visual.strength>=0 and m.visual.strength<=1)\n  if m.visual.priority then assert(type(m.visual.priority)=='number' and m.visual.priority%1==0 and m.visual.priority>=0 and m.visual.priority<=100) end\n  for key in m.text:gmatch('{([a-z_]+)%%?}') do for _,tier in ipairs(m.tiers) do assert(type(tier[key])=='number','unknown tooltip tier') end end\n  return true\n end\n function S.resolve(v,m,tier) if type(v)=='string' then return m.tiers[tier or 1][v:sub(2)] end;return v end\n function S.tooltip(m,tier)\n  S.validate(m);local text=m.text:gsub('{([a-z_]+)(%%?)}',function(k,pct) local v=assert(m.tiers[tier or 1][k],'unknown tooltip tier');return pct=='%' and tostring(v*100)..'%' or tostring(v) end)\n  return m.label..': '..text..(m.cost and ' Cost: '..m.cost or '')\n end\n return S\nend\n", "@envoy/mod_schema.lua", "t"))()(envoy)
envoy.mod_codec = assert(load("-- Canonical bounded data encoding. No load(), functions, metatables or wall clock.\nreturn function()\n local C={}\n function C.encode(value)\n  local nodes,active=0,{}\n  local function pack(v,depth)\n   nodes=nodes+1;assert(nodes<=6000 and depth<=20,'modifier state too complex')\n   local kind=type(v)\n   if kind=='boolean' then return v and 't' or 'f' end\n   if kind=='number' then assert(v==v and math.abs(v)<1e15,'non-finite state');local s=string.format('%.17g',v);return 'd'..#s..':'..s end\n   if kind=='string' then return 's'..#v..':'..v end\n   assert(kind=='table' and not getmetatable(v) and not active[v],'plain acyclic state required');active[v]=true\n   local keys={};for k in pairs(v) do assert(type(k)=='string' or type(k)=='number' and k%1==0,'invalid state key');keys[#keys+1]=k end\n   assert(#keys<=512,'checkpoint table too large')\n   table.sort(keys,function(a,b) if type(a)~=type(b) then return type(a)=='number' end;return a<b end)\n   local out={'{'..#keys..':'};for _,k in ipairs(keys) do out[#out+1]=pack(k,depth+1);out[#out+1]=pack(v[k],depth+1) end\n   active[v]=nil;return table.concat(out)\n  end\n  local out=pack(value,0);assert(#out<=16384,'modifier checkpoint exceeds 16 KiB');return out\n end\n function C.decode(text)\n  assert(type(text)=='string' and #text<=16384,'invalid modifier checkpoint');local at,nodes=1,0\n  local function count()\n   local endat=text:find(':',at,true);assert(endat and endat-at<7,'invalid checkpoint length')\n   local s=text:sub(at,endat-1);assert(s:match('^%d+$'),'invalid checkpoint count');at=endat+1;return tonumber(s)\n  end\n  local function read(depth)\n   nodes=nodes+1;assert(nodes<=6000 and depth<=20,'checkpoint too complex')\n   local kind=text:sub(at,at);at=at+1\n   if kind=='t' then return true elseif kind=='f' then return false end\n   if kind=='s' or kind=='d' then\n    local n=count();assert(at+n-1<=#text,'truncated checkpoint');local s=text:sub(at,at+n-1);at=at+n\n    if kind=='s' then return s end;local v=tonumber(s);assert(v and v==v and math.abs(v)<1e15,'invalid state number');return v\n   end\n   assert(kind=='{','invalid checkpoint type');local n=count();assert(n<=512,'checkpoint table too large');local out={}\n   for _=1,n do local k=read(depth+1);assert(type(k)=='string' or type(k)=='number' and k%1==0,'invalid checkpoint key');assert(out[k]==nil,'duplicate checkpoint key');out[k]=read(depth+1) end\n   return out\n  end\n  local out=read(0);assert(at==#text+1,'trailing checkpoint bytes');return out\n end\n return C\nend\n", "@envoy/mod_codec.lua", "t"))()(envoy)
envoy.mod_engine = assert(load("-- Pure bounded rule evaluation. Native adapter owns checkpointed gameplay writes.\nreturn function(D)\n local S,C=D.mod_schema,D.mod_codec;local E={};E.__index=E\n local ordered={'burn','shock','chill','curse','haste','guarded','momentum'}\n local status_tags={burn='burning',chill='chilled',curse='cursed',haste='hasted',guarded='guarded',momentum='momentum'}\n local function copy(v) return C.decode(C.encode(v)) end\n local function append(out,text) for _,v in ipairs(out) do if v==text then return end end;if #out<24 then out[#out+1]=text end end\n function E.new(seed,pool,limits)\n  seed=seed or 1;limits=limits or {};assert(type(seed)=='number' and seed%1==0 and seed>=1 and seed<2147483647,'invalid seed')\n  local budget,depth=limits.budget or 64,limits.depth or 8\n  assert(type(budget)=='number' and budget%1==0 and budget>=1 and budget<=128 and type(depth)=='number' and depth%1==0 and depth>=1 and depth<=16,'invalid limits')\n  local rules={};local list={};for _,m in ipairs(pool) do S.validate(m);assert(not rules[m.id],'duplicate modifier');rules[m.id]=m;list[#list+1]=m end\n  table.sort(list,function(a,b) return a.id<b.id end)\n  return setmetatable({rules=rules,list=list,seed=seed or 1,frame=0,equipped={},statuses={},recent={},players={},queue={},damage={},trace={},used=0,dropped=0,\n   limit=budget,depth=depth,display={last_pulse=-30,pulse_start=-100,pulse_strength=0,trace_key='',intensity=.65}},E)\n end\n function E:random() self.seed=self.seed*48271%2147483647;return self.seed/2147483647 end\n function E:equip(port,id,tier)\n  assert(type(port)=='number' and port%1==0 and port>=1 and port<=6,'port 1..6 required')\n  local m=assert(self.rules[id],'unknown modifier');tier=tier or 1;assert(m.tiers[tier],'unknown tier')\n  local at=self.equipped[port] or {};if m.kind=='keystone' then for other in pairs(at) do assert(self.rules[other].kind~='keystone' or other==id,'one keystone') end end\n  at[id]=tier;self.equipped[port]=at\n end\n function E:status(port,name) return (self.statuses[port] or {})[name] end\n function E:clear(port)\n  if port then self.equipped[port]=nil;self.statuses[port]=nil;self.recent[port]=nil;self.damage[port]=nil\n  else self.equipped={};self.statuses={};self.recent={};self.damage={};self.queue={};self.trace={} end\n end\n function E:emit(e)\n  assert(S.events[e.kind],'unsupported modifier event')\n  e=copy(e);e.depth=e.depth or 1;e.tags=e.tags or {};e.origin=e.origin or {}\n  assert(type(e.port)=='number' and e.port%1==0 and e.port>=1 and e.port<=6,'invalid event port')\n  if e.target then assert(type(e.target)=='number' and e.target%1==0 and e.target>=1 and e.target<=6,'invalid event target') end\n  for tag,v in pairs(e.tags) do assert(S.tags[tag] and type(v)=='boolean','unsupported event tag') end\n  assert(type(e.depth)=='number' and e.depth%1==0 and e.depth>=1,'invalid event depth')\n  if e.depth>self.depth or #self.queue>=128 then self.dropped=self.dropped+1;return false end\n  self.queue[#self.queue+1]=e;return true\n end\n function E:begin_frame(players)\n  self.frame=self.frame+1;self.players=copy(players or {});self.damage={};self.used=0\n  for port=1,6 do local statuses=self.statuses[port]\n   if statuses then for _,name in ipairs(ordered) do local v=statuses[name]\n    if v then\n     if name=='burn' and v.next_tick<=self.frame then\n      self.damage[port]=(self.damage[port] or 0)+v.amount*v.stacks;v.next_tick=v.next_tick+60\n     end\n     if v.expires<=self.frame then\n      statuses[name]=nil;self:emit{kind='status_removed',port=port,status=name,tags={},origin=v.origin}\n     end\n    end\n   end end\n  end\n  for port=1,6 do if self.players[port] then self:emit{kind='interval',port=port,tags={}} end end\n end\n function E:matches(m,e,tier)\n  if m.trigger~=e.kind then return false end\n  if m.trigger=='interval' and self.frame%S.resolve(m.interval,m,tier)~=0 then return false end\n  local own=e.self_context or self.players[e.port] or {};local target=e.target_context or self.players[e.target] or {}\n  for _,c in ipairs(m.conditions or {}) do for k,v in pairs(c) do\n   if type(v)=='string' and v:sub(1,1)=='$' then v=S.resolve(v,m,tier) end\n   if k=='tag' and not e.tags[v] then return false\n   elseif k=='status' and (v=='any' and not e.status or v~='any' and e.status~=v) then return false\n   elseif k=='self_status' or k=='target_status' then\n    local at=self.statuses[k=='self_status' and e.port or e.target] or {}\n    if v=='any' then if next(at)==nil then return false end elseif not at[v] then return false end\n   elseif k=='self_damage_above' and (own.percent==nil or own.percent<=v) then return false\n   elseif k=='self_damage_below' and (own.percent==nil or own.percent>=v) then return false\n   elseif k=='target_damage_above' and (target.percent==nil or target.percent<=v) then return false\n   elseif k=='grounded' and (own.grounded==nil or (own.grounded==true)~=v) then return false\n   elseif k=='airborne' and (own.grounded==nil or (own.grounded==false)~=v) then return false\n   elseif k=='last_stock' and ((own.stocks or 0)==1)~=v then return false\n   elseif k=='stage_kind' and e.stage_kind~=v then return false\n   elseif k=='recently' then local f=(self.recent[e.port] or {})[v.event];if not f or self.frame-f>S.resolve(v.frames,m,tier) then return false end end\n  end end\n  return true\n end\n local function ancestry(self,m,e)\n  local out=copy(e.origin)\n  for _,c in ipairs(m.conditions or {}) do\n   for _,key in ipairs({'self_status','target_status'}) do local name=c[key]\n    if name then local at=self.statuses[key=='self_status' and e.port or e.target] or {}\n     for _,status in ipairs(ordered) do if name=='any' or name==status then for _,line in ipairs((at[status] or {}).origin or {}) do append(out,line) end end end\n    end\n   end\n  end\n  return out\n end\n function E:apply(m,e,tier)\n  local origin=ancestry(self,m,e)\n  for _,effect in ipairs(m.effects) do\n   if self.used>=self.limit then self.dropped=self.dropped+1;break end\n   if not effect.when or effect.when==e.kind then\n    self.used=self.used+1;local port=effect.subject=='target' and e.target or e.port\n    if port and self.players[port] then\n     local value=function(v) return S.resolve(v,m,tier) end;local label=m.label\n     if effect.op=='status' or effect.op=='stacks' then\n      local duration=math.floor(value(effect.duration));assert(duration>=1 and duration<=3600,'status duration out of bounds')\n      local at=self.statuses[port] or {};self.statuses[port]=at;local v=at[effect.status];local expires=self.frame+duration\n      local amount=value(effect.amount or 1)\n      if v then\n       v.stacks=math.min(effect.max,v.stacks+1)\n       if effect.refresh=='refresh' then v.expires=expires elseif effect.refresh=='extend' then v.expires=math.min(self.frame+3600,v.expires+duration) end\n       v.amount=math.max(v.amount,amount)\n      else v={expires=expires,stacks=1,max=effect.max,amount=amount,next_tick=self.frame+60,origin={}};at[effect.status]=v end\n      append(origin,effect.status..' applied by '..label);v.origin=copy(origin)\n      self:emit{kind='status_applied',port=port,target=e.target,status=effect.status,tags={[status_tags[effect.status]]=true},depth=e.depth+1,origin=origin}\n      if effect.op=='stacks' or v.stacks>1 then self:emit{kind='stacks_changed',port=port,status=effect.status,tags={[status_tags[effect.status]]=true},depth=e.depth+1,origin=origin} end\n     elseif effect.op=='remove_status' then\n      if self:status(port,effect.status) then self.statuses[port][effect.status]=nil;append(origin,effect.status..' spent by '..label)\n       self:emit{kind='status_removed',port=port,status=effect.status,tags={},depth=e.depth+1,origin=origin}\n      end\n     elseif effect.op=='heal' or effect.op=='damage' then\n      local amount=value(effect.amount);self.damage[port]=(self.damage[port] or 0)+(effect.op=='heal' and -amount or amount)\n      append(origin,(effect.op=='heal' and 'heal ' or 'damage ')..amount..' from '..label)\n     elseif effect.op=='emit' then\n      append(origin,'event from '..label);self:emit{kind=effect.event,port=port,target=e.target,tags={[effect.tag]=true},depth=e.depth+1,origin=origin}\n     end\n    end\n   end\n  end\n  if #origin>0 then self.trace=origin;self.display.trace_generation=(self.display.trace_generation or 0)+1 end\n end\n function E:drain()\n  local at=1\n  while at<=#self.queue do\n   local e=self.queue[at];at=at+1\n   if e.native_trace and #e.origin>0 then\n    self.trace=copy(e.origin);self.display.trace_generation=(self.display.trace_generation or 0)+1\n    -- Remember real native use of a status for later KO ancestry; no new status\n    -- or gameplay effect is invented by this provenance annotation.\n    for _,name in ipairs(e.native_statuses or {}) do local v=self:status(e.target,name);if v then v.origin=copy(e.origin) end end\n   end\n   if self.used>=self.limit then self.dropped=self.dropped+1 end\n   self.recent[e.port]=self.recent[e.port] or {};self.recent[e.port][e.kind]=self.frame\n   for _,m in ipairs(self.list) do local tier=(self.equipped[e.port] or {})[m.id]\n    if self.used<self.limit and tier and self:matches(m,e,tier) then self:apply(m,e,tier) end\n   end\n   -- A lost stock ends what was happening to the fighter (statuses, stacks, recent events), not the build:\n   -- equipped modifiers stay and their steady effects, looks and hit rules are derived again from them.\n   if e.kind=='stock_lost' then self.statuses[e.port]=nil;self.recent[e.port]=nil;self.damage[e.port]=nil end\n  end\n  self.queue={}\n end\n function E:values(port)\n  local out={};local function mul(key,value) out[key]=math.max(.1,math.min(4,(out[key] or 1)*value)) end\n  for _,m in ipairs(self.list) do local tier=(self.equipped[port] or {})[m.id]\n   if tier and m.trigger=='equip' then for _,effect in ipairs(m.effects) do if effect.op=='value' then mul(effect.key,S.resolve(effect.value,m,tier)) end end end\n  end\n  for _,name in ipairs(ordered) do local v=self:status(port,name)\n   if v then\n    if name=='chill' then mul('run_speed',.8);mul('air_speed',.8)\n    elseif name=='curse' then mul('knockback_taken',1+v.amount)\n    elseif name=='haste' then mul('run_speed',1.2);mul('air_speed',1.2)\n    elseif name=='guarded' then mul('damage_taken',.75);mul('knockback_taken',.85) end\n   end\n  end\n  return out\n end\n function E:native_rules(port)\n  local out,bits={},0\n  for _,name in ipairs(ordered) do if self:status(port,name) then bits=bits+(S.status_bits[name] or 0) end end\n  for i,m in ipairs(self.list) do local tier=(self.equipped[port] or {})[m.id]\n   if tier then for j,effect in ipairs(m.effects) do\n    if effect.op=='convert' or effect.op=='versus-status' then\n     local match,change=copy(effect.match),{}\n     match.move=match.move or 'any';if effect.status then match.status_bits=S.status_bits[effect.status] end\n     for k,v in pairs(effect.change) do change[k]=k=='element' and v or S.resolve(v,m,tier) end\n     out[#out+1]={id=i*8+j,match=match,change=change}\n    end\n   end end\n  end\n  assert(#out<=8,'native hit rule capacity exceeded');return out,bits\n end\n function E:native_origin(ids,target)\n  local out,used={},{}\n  for _,id in ipairs(ids or {}) do\n   if type(id)=='number' and id%1==0 then local m=self.list[math.floor((id-1)/8)];local effect=m and m.effects[(id-1)%8+1]\n    if effect and (effect.op=='convert' or effect.op=='versus-status') then\n     if effect.status then used[#used+1]=effect.status;for _,line in ipairs((self:status(target,effect.status) or {}).origin or {}) do append(out,line) end end\n     local action=effect.change.element and 'hit converted to '..effect.change.element or effect.change.knockback_taken and 'launch boosted' or 'hit damage scaled'\n     append(out,action..' by '..m.label)\n    end\n   end\n  end\n  return out,used\n end\n function E:export()\n  assert(#self.queue==0,'checkpoint requires a drained event boundary')\n  return C.encode{version=1,seed=self.seed,frame=self.frame,equipped=self.equipped,statuses=self.statuses,recent=self.recent,trace=self.trace,dropped=self.dropped,limit=self.limit,depth=self.depth,display=self.display}\n end\n function E:import(text)\n  local at=C.decode(text);assert(at.version==1 and type(at.frame)=='number' and at.frame%1==0 and at.frame>=0,'invalid modifier snapshot')\n  assert(type(at.seed)=='number' and at.seed%1==0 and at.seed>=1 and at.seed<2147483647,'invalid random state')\n  assert(type(at.limit)=='number' and at.limit>=1 and at.limit<=128 and at.limit%1==0 and type(at.depth)=='number' and at.depth>=1 and at.depth<=16 and at.depth%1==0,'invalid snapshot budget')\n  for p,mods in pairs(at.equipped) do assert(type(p)=='number' and p>=1 and p<=6 and p%1==0)\n   for id,tier in pairs(mods) do assert(self.rules[id] and self.rules[id].tiers[tier],'unknown snapshot modifier') end\n  end\n  for p,statuses in pairs(at.statuses) do assert(type(p)=='number' and p>=1 and p<=6 and p%1==0)\n   for name,v in pairs(statuses) do assert(S.statuses[name] and type(v)=='table' and v.stacks>=1 and v.stacks<=8 and v.stacks%1==0 and v.max>=v.stacks and v.max<=8 and v.expires>=at.frame and v.expires%1==0 and v.next_tick%1==0 and v.amount>=0 and v.amount<=100 and type(v.origin)=='table','invalid snapshot status') end\n  end\n  for p,events in pairs(at.recent) do assert(type(p)=='number' and p%1==0 and p>=1 and p<=6);for event,frame in pairs(events) do assert(S.events[event] and type(frame)=='number' and frame%1==0 and frame>=0 and frame<=at.frame,'invalid recent event') end end\n  assert(type(at.trace)=='table' and #at.trace<=24 and type(at.dropped)=='number' and at.dropped>=0 and at.dropped%1==0,'invalid snapshot trace');for _,line in ipairs(at.trace) do assert(type(line)=='string' and #line<=160) end\n  assert(type(at.display)=='table' and type(at.display.intensity)=='number' and at.display.intensity>=0 and at.display.intensity<=1,'invalid display snapshot')\n  for _